head.script:
scwin.trigger3_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var data = {
        name: "popup1"
    };
    var options = {
        id: "popup1",
        type: "iframePopup",
        width: "400px",
        height: "250px",
        modal: true,
        alwaysOnTop: false,
        dataObj: data
        //            , useModalStack: true
    };
    scwin.$w.openPopup("popup_modal_false_WEFF-423_(WSQ-3774)_child.xml", options);
};
scwin.trigger4_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var data = {
        name: "popup2"
    };
    var options = {
        id: "popup2",
        type: "iframePopup",
        width: "400px",
        height: "250px",
        modal: false,
        alwaysOnTop: false,
        dataObj: data
        //            , useModalStack: true
    };
    scwin.$w.openPopup("popup_modal_false_WEFF-423_(WSQ-3774)_child.xml", options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
